      partial: partial,
    ),
    'text_end' => TextEndEvent(
      contentIndex: index(),
      content: _requireString(encoded['content'], 'event.content'),
      partial: partial,
    ),
    'thinking_start' => ThinkingStartEvent(
      contentIndex: index(),
