        return (
          context: context,
          reliefUsed: true,
          retried: false,
          terminal: await _abortedTurn(context, config, emit),
        );
      }
    }
  }
  return (
    context: context,
    reliefUsed: true,
    retried: false,
    terminal: (
      await _finishWithoutStream(
        context,
        emit,
        _terminalMessage(
          config.model,
          StopReason.error,
          '$contextWindowExhaustedMarker: the outgoing context is '
          '~$tokens tokens, '
          'the ${config.model.id} effective window is $window. The request '
          'was not sent. Auto-compaction runs next; if it keeps failing, '
          'run /compact or start a fresh session.',
        ),
      ),
      context,
    ),
  );
}

/// Whether the host's one-shot over-window relief is still on the table.
bool _reliefAvailable(bool reliefUsed, AgentLoopConfig config) =>
    !reliefUsed && config.overWindowRelief != null;

/// Whether the run was cancelled before its request went out.
bool _isCancelRequested(CancelToken? cancelToken) =>
    cancelToken != null && cancelToken.isCancelled;

/// The already-cancelled turn: no request leaves the loop.
Future<(AssistantMessage, Context)> _abortedTurn(
  Context context,
  AgentLoopConfig config,
  AgentEventSink emit,
) async {
  return (
    await _finishWithoutStream(
      context,
      emit,
      _terminalMessage(config.model, StopReason.aborted, 'Operation aborted'),
    ),
    context,
  );
}

/// A provider/runtime error thrown by the stream call itself becomes an
/// error turn, not a crash.
Future<(AssistantMessage, Context)> _providerErrorTurn(
  Context context,
  AgentLoopConfig config,
  AgentEventSink emit,
  Object error,
) async {
  return (
    await _finishWithoutStream(
      context,
      emit,
      _terminalMessage(config.model, StopReason.error, '$error'),
    ),
    context,
  );
}

/// Whether a finished turn needs the one-shot pairing self-heal (issue
/// #85): a provider pairing 400 on an error stop, before it was used.
bool _needsPairingHeal(bool pairingHealed, AssistantMessage finished) =>
    !pairingHealed &&
    finished.stopReason == StopReason.error &&
    isToolPairingProviderError(finished.errorMessage);

/// Builds the synthetic error turn for a provider stream that closed
/// without any terminal event (provider bug): keep the streamed partial
/// when one landed, otherwise synthesize an empty error message.
AssistantMessage _streamEndedWithoutTerminal(
  AgentLoopConfig config,
  AssistantMessage? partial,
) {
  const errorText = 'Provider stream ended without a terminal event';
  return (partial ??
          _terminalMessage(config.model, StopReason.error, errorText))
      .copyWith(stopReason: StopReason.error, errorMessage: errorText);
}

/// Applies the request-payload rewrites before a provider call: the
/// `transformContext` hook and the symmetric tool-pairing repair. Only the
/// request payload is rewritten, never the transcript. Returns the payload
/// plus what the pairing repair changed (empty when nothing did).
Future<(Context, ToolPairingRepairReport)> _buildRequestContext(
  Context context,
  AgentLoopConfig config,
  CancelToken? cancelToken, {
  String? misuseNote,
}) async {
  // pi applies transformContext (then convertToLlm) before each provider
  // call; only the request payload is rewritten, never the transcript.
  var requestContext = context;
  final transformContext = config.transformContext;
  if (transformContext != null) {
    requestContext = Context(
      systemPrompt: context.systemPrompt,
      messages: await transformContext(List.of(context.messages), cancelToken),
      tools: context.tools,
    );
  }
  // Session image registry (#171): unique history images ride once as
  // `[Image N]` carriers; every other occurrence becomes a text ref.
  // Payload-only rewrite — the transcript is never touched, and the
  // kill switch (`images.registry: false`) skips it entirely.
  if (imageRegistryConfig.enabled) {
    final rewritten = rewriteHistoryImages(
      requestContext.messages,
      onDrop: imageDropNotice,
    );
    if (!identical(rewritten, requestContext.messages)) {
      requestContext = Context(
        systemPrompt: requestContext.systemPrompt,
        messages: rewritten,
        tools: requestContext.tools,
      );
    }
  }
  // gh-1409: compaction-pinned skill operative lines ride every
  // post-boundary request as the verbatim carrier (AC2) — payload-only,
  // the transcript is never touched; the kill switch
  // (`operativePinConfig.enabled = false`) skips it entirely. Runs BEFORE
  // tool-pairing repair: the carrier is a standalone user message and can
  // never break a call/result run (it anchors outside them).
