    'error' => ErrorEvent(
      reason: _decodeStopReason(_requireString(encoded['reason'], 'reason')),
      error: partial,
      retryAfter: encoded['retryAfterMs'] is int
          ? Duration(milliseconds: encoded['retryAfterMs'] as int)
