        final shownDetail = config.redactionPipeline?.redact(detail) ?? detail;
        io.writeln(
          '[stuck-call] $toolName: ${action.label} after '
          '${elapsed.inSeconds}s${shownDetail.isEmpty ? '' : ' — $shownDetail'}',
