    var reliefCalls = 0;
    final stream = agentLoop(
      prompts: [UserMessage.text('u' * 300)],
      context: const Context(messages: [], tools: [_bashTool]),
      config: AgentLoopConfig(
        model: _model,
        overWindowRelief: (messages) async {
          reliefCalls++;
