MessageCapRefusal? classifyMessageCapError(String? errorMessage) {
  if (errorMessage == null || errorMessage.isEmpty) return null;
  final isNonOverflow = _nonOverflowPatterns.any(
    (pattern) => pattern.hasMatch(errorMessage),
