  Future<void> _onAgentEvent(AgentEvent event, CancelToken cancelToken) async {
    _lastAgentEventAt = DateTime.now(); // #437 steering heartbeat
    // Run-lifecycle forensics to fa.log: one line per phase transition, so
    // a wedged "Working…"/"Compacting…" row can be attributed to the exact
    // phase (provider turn vs named tool vs run) that never finished.
    _logEventForensics(event);
    await _persistEventLiveness(event);
    await _persistIncremental(event);
    // Reasoning-phase liveness (gh-1198 tier 2 + gh-1430): a request
    // going out arms the silent-window watch AND the stream heartbeat
    // (line mode/headless with the thinking stream off); tier 2 treats
    // ANY event as visible progress, while the heartbeat classifies —
    // rendered output disarms it, unrendered stream events prove
    // aliveness (the headless thinking-delta window the bench round-4
    // kills lived in).
    if (event is ModelRequestEvent) {
      _waiting.reasoningRequestStarted();
    } else {
      _waiting.reasoningProgress(event);
    }
    await handleAgentEvent(
      event,
      onMessageLifecycle: _onMessageLifecycle,
      onMessageUpdate: _onMessageUpdate,
      onToolExecutionStart: _onToolExecutionStart,
      onToolExecutionEnd: _onToolExecutionEnd,
      onTurnEnd: (message) => _usage.add(message.usage),
      onModelRequest: _onModelRequest,
      onTaskLedger: _onTaskLedger,
    );
  }

  /// fa.log forensics for the phase-transition events (the plain
  /// diagnostic cases of [_onAgentEvent]; the record-persisting cases
import '../agent/agent_loop.dart';
import '../types.dart';

/// Routes an [AgentEvent] to the appropriate UI callback.
///
/// Pulled out of [AgentCli] so the switch complexity can be unit-tested
/// without spinning up a full CLI instance.
Future<void> handleAgentEvent(
  AgentEvent event, {
  required void Function(Message message, {required bool start})
  onMessageLifecycle,
  required void Function(AssistantMessageEvent) onMessageUpdate,
  required void Function(
    String toolCallId,
    String toolName,
    Map<String, dynamic> args,
  )
  onToolExecutionStart,
  required void Function(
    String toolCallId,
    String toolName,
    ToolExecutionResult result, {
    required bool isError,
  })
  onToolExecutionEnd,
  required void Function(AssistantMessage message) onTurnEnd,
  Future<void> Function(ModelRequestEvent event)? onModelRequest,
  Future<void> Function(TaskLedgerEvent event)? onTaskLedger,
}) async {
  switch (event) {
    case MessageStartEvent(:final message) || MessageEndEvent(:final message):
      onMessageLifecycle(message, start: event is MessageStartEvent);
    case MessageUpdateEvent(:final assistantMessageEvent):
      onMessageUpdate(assistantMessageEvent);
    case ToolExecutionStartEvent(
      :final toolCallId,
      :final toolName,
      :final args,
    ):
      onToolExecutionStart(toolCallId, toolName, args);
    case ToolExecutionEndEvent(
      :final toolCallId,
      :final toolName,
      :final result,
      :final isError,
    ):
      onToolExecutionEnd(toolCallId, toolName, result, isError: isError);
    case TurnEndEvent(:final message):
      onTurnEnd(message);
    case ModelRequestEvent():
      await onModelRequest?.call(event);
    case TaskLedgerEvent():
      await onTaskLedger?.call(event);
    default:
  }
}

