        api: 'test-api',
        provider: 'test-provider',
        model: 'test-model',
        usage: Usage(
          input: totalTokens,
          output: 10,
          cacheRead: 0,
          cacheWrite: 0,
          totalTokens: totalTokens,
          cost: const UsageCost(
            input: 0,
            output: 0,
            cacheRead: 0,
            cacheWrite: 0,
            total: 0,
          ),

