      final store = ModelCapsStore();
      store.learnFromRefusal(
        _model,
        const MessageCapRefusal(maxMessages: 1024),
      );
      store.learnFromRefusal(
        _model,
        const MessageCapRefusal(maxMessages: 4096),
      );
      expect(store.learnedCapFor(_model), 4096);
