    throw const ConfigException('Cannot continue from message role: assistant');
  }

  final stream = AgentEventStream();
  _drive(
    stream,
    runAgentLoopContinue(
      context: context,
      config: config,
      emit: stream.push,
      streamFunction: streamFunction,
      toolExecutor: toolExecutor,
      cancelToken: cancelToken,
    ),
  );
  return stream;
}

