      // 990 >= 1000 * 0.99
      expect(
        isContextOverflow(lengthStopMessage(990, 0, 0), contextWindow: 1000),
        isTrue,
      );
      // 989 < 1000 * 0.99
      expect(
        isContextOverflow(lengthStopMessage(989, 0, 0), contextWindow: 1000),
        isFalse,
      );
    });
  });
}

