      expect(messageCapTriggerReached(100000, null), isFalse);
    });

    test('a custom margin is honored', () {
      expect(messageCapTriggerReached(2040, 2048, margin: 8), isFalse);
      expect(messageCapTriggerReached(2040, 2048, margin: 16), isTrue);
    });
