import 'package:test/test.dart';

import 'package:fa_llm_mock/fa_llm_mock.dart';

import 'pty_harness.dart';

void main() {
  late Directory tempHome;
  late Directory workspace;

  setUp(() {
    tempHome = Directory.systemTemp.createTempSync('headless_log_home_');
    File('${tempHome.path}/.fah/config.yaml')
      ..createSync(recursive: true)
      ..writeAsStringSync('approvalMode: yolo\n');
    workspace = Directory.systemTemp.createTempSync('headless_log_ws_');
  });

  tearDown(() {
    tempHome.deleteSync(recursive: true);
    workspace.deleteSync(recursive: true);
  });

  /// Spawns one headless `fah` prompt (temp HOME, `--cwd <workspace>`),
  /// same convention as `fa_cube_headless_helper.dart`, with [extraArgs]
  /// appended before the prompt and [extraEnv] merged into the child env.
  Future<ProcessResult> runHeadless(
    MockLlmServer server,
    List<String> extraArgs, {
    Map<String, String> extraEnv = const {},
  }) {
    // gh-1300: honor the FA_BIN AOT seam (compiled ONCE per CI shard).
    final command = faCliCommand(
      [
        '--provider',
        'openai-completions',
        '--base-url',
        server.baseUrl,
        '--model',
        'mock-model',
        '--cwd',
        workspace.path,
        ...extraArgs,
        '-p',
        'hi',
      ],
      jitPrefix: const ['dart', 'run', 'bin/fah.dart'],
    );
    return Process.run(
      command.first,
      command.sublist(1),
      workingDirectory: Directory.current.path,
      environment: {
        'OPENAI_API_KEY': 'mock',
        'HOME': tempHome.path,
        ...extraEnv,
      },
      stdoutEncoding: utf8,
      stderrEncoding: utf8,
    ).timeout(const Duration(minutes: 4));
  }

