    final envPath = '${workspace.path}/ignored-trace.log';
    final result = await runHeadless(
      server,
      ['--log-file', flagPath],
      extraEnv: {'FA_LOG_FILE': envPath},
    );
    expect(result.exitCode, 0, reason: '${result.stderr}');
